def sum_of_prime_factors_with_multiplicity(n):
    remaining = n
    factor = 2
    total = 0
    while factor * factor <= remaining:
        while remaining % factor == 0:
            total += factor
            remaining //= factor
        factor += 1
    if remaining > 1:
        total += remaining
    return total

