def is_alternating_case(s):
    letters = [ch for ch in s if ch.isalpha()]
    for idx in range(1, len(letters)):
        prev_upper = letters[idx - 1].isupper()
        curr_upper = letters[idx].isupper()
        if prev_upper == curr_upper:
            return False
    return True

