def days_until_next_birthday(birth_md, today_ymd):
    def is_leap(y):
        return (y % 4 == 0 and y % 100 != 0) or y % 400 == 0
    def dim(y, m):
        lens = [31, 29 if is_leap(y) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        return lens[m - 1]
    def ordinal(y, m, d):
        total = d
        for month in range(1, m):
            total += dim(y, month)
        return total
    bm, bd = birth_md
    ty, tm, td = today_ymd
    t_ord = ordinal(ty, tm, td)
    b_ord = ordinal(ty, bm, bd)
    if b_ord >= t_ord:
        return b_ord - t_ord
    days_left_this_year = (366 if is_leap(ty) else 365) - t_ord
    return days_left_this_year + ordinal(ty + 1, bm, bd)

